from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.mobile.gnb.oam.coam.classical.pages.navigatable_page import NavigatablePage
from taf.selenium.mobile.gnb.oam.coam.classical.pages.modals import RollbackSoftwareModal


class SoftwareManagementPage(NavigatablePage):
    ROLLBACK_BUTTON_XPATH = "//button[contains(text(), 'Rollback...')]"
    VERSION_KEYS_XPATH = "//ui-list-item//label"
    VERSION_VALUES_XPATH = "//ui-list-item//label/following-sibling::div"

    def __init__(self, tool):
        super(SoftwareManagementPage, self).__init__(tool)

    def software_rollback(self):
        self._tool.click_enabled_element_after_visible((By.XPATH, self.ROLLBACK_BUTTON_XPATH))
        rollback_software_modal = RollbackSoftwareModal(self._tool)
        rollback_software_modal.wait_until_rollback_software_modal_appear()
        rollback_software_modal.confirm()

    def check_current_software_version(self, key):
        version = self._tool.get_dict_from_elements_by_xpath(self.VERSION_KEYS_XPATH, self.VERSION_VALUES_XPATH, ':')
        return version if key is None else version[key]
